import { test, expect } from "@playwright/test";
import {
  beginDenseWindow,
  endDenseWindow,
  denseStreamObservations,
} from "../../helpers/dense-measurement";

test("records visible stream progress during the measured window", async ({ page }) => {
  test.setTimeout(30_000);
  await page.setContent(
    '<section data-testid="thread-column-one"><div data-agent-message-body>Dense canonical warmup Dense canonical tick 1</div></section>',
  );
  await page.evaluate(() => {
    (window as Window & { __KANDEV_E2E_STORE__?: unknown }).__KANDEV_E2E_STORE__ = {
      subscribe: () => () => undefined,
    };
  });
  const cdp = await page.context().newCDPSession(page);
  await cdp.send("Performance.enable", { timeDomain: "timeTicks" });
  const before = await beginDenseWindow(page, cdp, ["one"]);
  await expect
    .poll(async () => (await denseStreamObservations(page)).length, { timeout: 8_000 })
    .toBe(1);
  await page.locator("[data-agent-message-body]").evaluate((body) => {
    body.textContent = "Dense canonical warmup Dense canonical tick 5";
  });
  await expect
    .poll(async () => (await denseStreamObservations(page)).length, { timeout: 8_000 })
    .toBe(2);
  const after = await endDenseWindow(page, cdp, before);
  expect(after.browser.streamProgress.map((sample) => sample.rows)).toEqual([
    [{ taskId: "one", connected: true, lastTick: 1 }],
    [{ taskId: "one", connected: true, lastTick: 5 }],
  ]);
  await expect(beginDenseWindow(page, cdp, ["missing"])).rejects.toThrow(
    "Missing dense stream body",
  );
});

import { describe, expect, it, vi } from "vitest";
import type { StoreApi } from "zustand";
import type { AppState } from "@/lib/state/store";
import { createMessageUpdateScheduler } from "./messages";

function makePayload(session_id: string, message_id: string, content: string) {
  return {
    task_id: "task",
    session_id,
    message_id,
    content,
    author_type: "agent" as const,
    author_id: "agent",
    type: "message",
    created_at: "2026-08-02T00:00:00Z",
  };
}

function makeStore() {
  const updateMessages = vi.fn();
  const store = { getState: () => ({ messages: { bySession: {} }, updateMessages }) };
  return { store: store as unknown as StoreApi<AppState>, updateMessages };
}

function makeFrameScheduler() {
  let callback: (() => void) | null = null;
  return {
    schedule: (next: () => void) => {
      callback = next;
      return 1;
    },
    cancel: () => {
      callback = null;
    },
    runFrame: () => {
      const next = callback;
      callback = null;
      next?.();
    },
  };
}

describe("hidden-document message scheduling", () => {
  it("flushes before frame suspension, publishes while hidden, and removes its listener", () => {
    const doc = Object.assign(new EventTarget(), { visibilityState: "visible" });
    const remove = vi.spyOn(doc, "removeEventListener");
    vi.stubGlobal("document", doc);
    const { store, updateMessages } = makeStore();
    const frame = makeFrameScheduler();
    const scheduler = createMessageUpdateScheduler(store, frame);
    try {
      scheduler.enqueue(makePayload("session-1", "message-1", "pending"));
      doc.visibilityState = "hidden";
      doc.dispatchEvent(new Event("visibilitychange"));
      expect(updateMessages).toHaveBeenCalledExactlyOnceWith([
        expect.objectContaining({ content: "pending" }),
      ]);
      frame.runFrame();
      expect(updateMessages).toHaveBeenCalledTimes(1);
      scheduler.enqueue(makePayload("session-2", "message-2", "hidden"));
      expect(updateMessages).toHaveBeenCalledTimes(2);
      doc.visibilityState = "visible";
      doc.dispatchEvent(new Event("visibilitychange"));
      scheduler.enqueue(makePayload("session-1", "message-1", "foreground"));
      expect(updateMessages).toHaveBeenCalledTimes(2);
      frame.runFrame();
      expect(updateMessages).toHaveBeenCalledTimes(3);
      scheduler.dispose();
      expect(remove).toHaveBeenCalledWith("visibilitychange", expect.any(Function));
    } finally {
      scheduler.dispose();
      vi.unstubAllGlobals();
    }
  });
});
